import pandas as pd,numpy as np,json
from pathlib import Path
O=Path('work/sol-ncri/confounds');d=pd.read_csv(O/'items.csv');m=pd.read_csv(O/'models.csv');g=d.groupby('provider').agg(n=('compliance','size'),models=('model','nunique'),labs=('lab','nunique'),k=('compliance','sum'),score=('compliance','mean'),chars=('chars','mean'),cap=('cap','mean'),accuracy=('correct','mean'));g.to_csv(O/'provider_summary.csv');g=d.groupby(['model','provider']).agg(n=('compliance','size'),k=('compliance','sum'),score=('compliance','mean'),chars=('chars','mean'),cap=('cap','mean'),accuracy=('correct','mean'));g.to_csv(O/'model_provider.csv')
y=m.score.values;fit=m.groupby('lab').score.transform('mean').values;print(json.dumps({'lab_descriptive_eta2':1-sum((y-fit)**2)/sum((y-y.mean())**2),'n_labs':m.lab.nunique(),'n_providers':d.provider.nunique(),'providers_multiple_labs':int((d.groupby('provider').lab.nunique()>1).sum()),'models_multiple_providers':int((d.groupby('model').provider.nunique()>1).sum())},indent=2))
